using System.Text;
using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace Pharmacie.Wpf;
public partial class MainWindow:Window{readonly PharmacyData data;public MainWindow(){InitializeComponent();data=DataStore.Load();ShowDashboard();}TextBlock Txt(string t,int size=16)=>new(){Text=t,FontSize=size,Margin=new Thickness(0,6,0,6)};void Clear(string title){PageTitle.Text=title;Content.Children.Clear();}void ShowDashboard(){Clear("Tableau de bord");Content.Children.Add(Txt("Bonjour Alain,",28));Content.Children.Add(Txt("Ventes, stock et alertes de votre pharmacie",16));Content.Children.Add(Txt($"Produits actifs : {data.Products.Count}    |    Ruptures : {data.Products.Count(p=>p.Stock==0)}    |    Ventes enregistrées : {data.Sales.Count}",20));}void ShowProducts(){Clear("Produits");Content.Children.Add(Txt("Catalogue des produits",26));var grid=new DataGrid{ItemsSource=data.Products,AutoGenerateColumns=true,IsReadOnly=true,Height=320};Content.Children.Add(grid);var b=new Button{Content="Ajouter un produit de démonstration",Padding=new Thickness(12),Margin=new Thickness(0,12,0,0)};b.Click+=(s,e)=>{data.Products.Add(new Product{Reference="NEW-001",Name="Nouveau produit",Category="Divers",Price=1000,Stock=10,Minimum=3,Lot="LOT-NEW",Expiry=DateTime.Today.AddYears(1)});DataStore.Save(data);ShowProducts();};Content.Children.Add(b);}void ShowSale(){Clear("Vente & caisse");Content.Children.Add(Txt("Sélectionnez un produit",24));foreach(var p in data.Products.Where(p=>p.Stock>0)){var b=new Button{Content=$"{p.Name} - {p.Price:N0} FCFA - Stock : {p.Stock}",Padding=new Thickness(12),Margin=new Thickness(0,6,0,0)};b.Click+=(s,e)=>{p.Stock--;data.Sales.Add(new Sale{Number="V-"+(data.Sales.Count+1001),Date=DateTime.Now,Total=p.Price,Payment="Espèces"});DataStore.Save(data);MessageBox.Show($"Vente enregistrée : {p.Name}\nTotal : {p.Price:N0} FCFA","Vente validée");ShowSale();};Content.Children.Add(b);}}void ShowStock(){Clear("Stocks & approvisionnement");Content.Children.Add(Txt("Réceptions et inventaire",26));var receive=new Button{Content="Réceptionner 10 unités sur le premier produit",Padding=new Thickness(12),Margin=new Thickness(0,8,0,8)};receive.Click+=(s,e)=>{if(data.Products.Count>0)data.Products[0].Stock+=10;DataStore.Save(data);ShowStock();};Content.Children.Add(receive);var inventory=new Button{Content="Valider un inventaire de démonstration",Padding=new Thickness(12),Margin=new Thickness(0,0,0,12)};inventory.Click+=(s,e)=>{DataStore.Save(data);MessageBox.Show("Inventaire validé et sauvegardé.");};Content.Children.Add(inventory);Content.Children.Add(new DataGrid{ItemsSource=data.Products,AutoGenerateColumns=true,IsReadOnly=true,Height=300});}void ShowReports(){Clear("Rapports");Content.Children.Add(Txt("Rapport des ventes",26));Content.Children.Add(Txt($"Chiffre d'affaires : {data.Sales.Sum(s=>s.Total):N0} FCFA",20));Content.Children.Add(new DataGrid{ItemsSource=data.Sales,AutoGenerateColumns=true,IsReadOnly=true,Height=260});}void Simple(string t){Clear(t);Content.Children.Add(Txt($"Module {t} prêt à être complété.",22));}void Dashboard_Click(object s,RoutedEventArgs e)=>ShowDashboard();void Products_Click(object s,RoutedEventArgs e)=>ShowProducts();void Sale_Click(object s,RoutedEventArgs e)=>ShowSale();void Stock_Click(object s,RoutedEventArgs e)=>ShowStock();void Reports_Click(object s,RoutedEventArgs e)=>ShowReports();void Settings_Click(object s,RoutedEventArgs e)=>Simple("Paramètres");}
